// All people, providers, records and dates below are fictional design fixtures.
const records=[
{id:'policy',title:'Life insurance policy letter',file:'policy-letter-2019.pdf',type:'PDF',category:'Insurance',date:'Jun 12, 2019',issuer:'Cedar Life · fictional provider',flag:'Review suggested',intro:'Policy correspondence',text:'Dear Arun Rao,\n\nThis letter confirms the policy information held on June 12, 2019.',highlight:'Recorded coverage: $250,000. Primary beneficiary on file: Maya Rao.',end:'This historical letter does not confirm current policy status, premium payments, or any subsequent beneficiary changes. Contact the provider for current information.'},
{id:'will',title:'Will — family copy',file:'will-family-copy-2024.pdf',type:'PDF',category:'Estate records',date:'Feb 8, 2024',issuer:'Family archive · unsigned design sample',flag:'Review suggested',intro:'Extract from a family copy',text:'This fictional excerpt describes a direction for the estate.',highlight:'I name Priya Rao to receive the residue of my estate.',end:'The sample does not establish validity, legal authority, or the recipient of a separately designated insurance benefit. No other pages are included in this design fixture.'},
{id:'storage',title:'Storage renewal email',file:'storage-renewal.eml',type:'Email',category:'Personal belongings',date:'Sep 2, 2026',issuer:'Valley Storage · fictional provider',flag:'Source available',intro:'Your monthly storage renewal',text:'Hello Arun,\n\nYour storage space is scheduled to renew for another month.',highlight:'Monthly charge: $129. Please arrange collection of all belongings before closing the space.',end:'The message does not include an inventory. Arrange a visit and ask the provider about access requirements before making changes.'},
{id:'statement',title:'September account statement',file:'september-statement.csv',type:'CSV',category:'Subscriptions',date:'Sep 15, 2026',issuer:'Family sample · fictional transactions',flag:'Source available',intro:'Recurring transactions',text:'Two recurring charges are present in this sample statement.',highlight:'Sep 3 · Harbor Gym · $39.99\nSep 7 · Streamly · $15.49',end:'Total shown: $55.48. This statement alone does not prove account ownership, cancellation terms or future renewals.'},
{id:'medical',title:'Medical invoice',file:'medical-invoice.pdf',type:'PDF',category:'Bills',date:'Sep 10, 2026',issuer:'Cedar Clinic · fictional provider',flag:'Review suggested',intro:'Account balance notice',text:'This fictional invoice requests a response by September 30, 2026.',highlight:'Amount shown on September 10: $1,240.',end:'The invoice predates the payment receipt in this workspace. Ask the provider whether that payment was applied before relying on this amount.'},
{id:'receipt',title:'Payment receipt',file:'payment-receipt.eml',type:'Email',category:'Bills',date:'Sep 14, 2026',issuer:'Cedar Clinic · fictional provider',flag:'Source available',intro:'Thank you for your payment',text:'A payment acknowledgement was issued four days after the invoice.',highlight:'Payment received: $400. Date: September 14, 2026.',end:'This receipt does not confirm the current balance or explicitly link this payment to the September 10 invoice.'},
{id:'voice',title:'A note about the blue folder',file:'blue-folder-transcript.txt',type:'Transcript',category:'Personal belongings',date:'Jul 3, 2026',issuer:'Family voice-note transcript · fictional',flag:'Source available',intro:'Transcript excerpt',text:'Arun’s note to the family:',highlight:'“The savings bonds should be in the blue folder, in the hall closet. I meant to sort those out.”',end:'A mention is a lead to follow, not proof of an asset or its value. The prototype includes text only; no original recording is attached.'},
{id:'pension',title:'Former employer acknowledgement',file:'employer-acknowledgement.eml',type:'Email',category:'Notifications',date:'Sep 19, 2026',issuer:'Northline · fictional employer',flag:'Source available',intro:'We have received your notification',text:'Dear Priya,\n\nThank you for contacting the benefits team.',highlight:'Your notification has been received. A team member will follow up about any required documents.',end:'No benefit eligibility or payment amount has been confirmed. Your workspace note records the notification as sent.'}
];
const demoRecord={id:'sample-letter',title:'A letter for a rainy day',file:'rainy-day-letter.txt',type:'Transcript',category:'Memories',date:'Nov 17, 2023',issuer:'Fictional family archive',flag:'Source available',intro:'A letter for Priya',text:'For a day when things feel a little too much,',highlight:'“Make the tea first. The rest can wait a few minutes. You always did try to carry everything at once.”',end:'With love, Dad.\n\nAn original fictional passage written for this prototype.'};
const allRecords=()=>state.imported?[...records,demoRecord]:records;
const heading=(eyebrow,title,desc,action='')=>`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;
const statusNames={all:'All actions',ready:'Ready',review:'Needs review',waiting:'Waiting',done:'Completed'};
const documentLink=id=>{const d=allRecords().find(d=>d.id===id);return d?`<button class="source-link" data-action="document" data-id="${id}">${icon('files')}<span>${d.title}<small>${d.date} · ${d.type}</small></span>${icon('external')}</button>`:''};

function planPage(){const chosen=tasks.filter(t=>state.filter==='all'||status(t)===state.filter);return heading('YOUR NEXT CHAPTER, AT YOUR PACE','A plan you can breathe with.','A few practical steps. Every one connected to the record that brought it here.')+`<div class="plan-layout"><section><div class="filter-bar" role="group" aria-label="Filter actions">${Object.entries(statusNames).map(([key,label])=>`<button class="filter ${state.filter===key?'selected':''}" data-action="filter-plan" data-filter="${key}" aria-pressed="${state.filter===key}">${label}<span>${tasks.filter(t=>key==='all'||status(t)===key).length}</span></button>`).join('')}</div><div class="plan-list">${chosen.map((t,i)=>`<article class="plan-row ${status(t)==='done'?'is-done':''}"><div class="plan-track"><span>${status(t)==='done'?icon('check'):String(i+1).padStart(2,'0')}</span></div><div class="plan-content"><div class="row-overline">${t.category}<span class="pill ${status(t)==='review'?'amber':status(t)==='waiting'?'blue':'neutral'}">${statusNames[status(t)]}</span></div><h2><button data-task="${t.id}">${t.title}</button></h2><p>${t.description}</p><div class="plan-metadata"><span>${icon('calendar')}${t.date}</span><span>${icon('files')}${t.source}</span></div></div><button class="row-chevron" data-task="${t.id}" aria-label="Open ${t.title}">${icon('arrow')}</button></article>`).join('')||`<div class="empty-state">${icon('leaf')}<h2>A little breathing room.</h2><p>No actions in this view. Your other steps are still in All actions.</p></div>`}</div></section><aside class="plan-aside"><div class="gentle-note"><span class="eyebrow">A NOTE FOR TODAY</span><h2>Small steps still<br>move you forward.</h2><p>You can leave a task for later, or mark it waiting while someone gets back to you.</p><div class="leaf-mark">${icon('leaf')}</div></div><div class="aside-note">${icon('info')}<p>Dates here are fictional provider requests or personal reminders. No legal deadline has been calculated.</p></div><a class="text-link" href="#ask">Need help making sense of a step? ${icon('arrow')}</a></aside></div>`}
function openTask(id){const t=tasks.find(t=>t.id===id);if(!t)return;state.activeTask=id;modal(t.title,`<span class="pill ${status(t)==='review'?'amber':'neutral'}">${statusNames[status(t)]}</span><p style="margin-top:16px">${t.description}</p><div class="labelled-value"><span>Category</span><strong>${t.category}</strong></div><div class="labelled-value"><span>Timing</span><strong>${t.date}</strong></div>${t.value?`<div class="labelled-value"><span>Record mentions</span><strong>${t.value}</strong></div>`:''}<div class="dialog-section"><h3>Start with the source</h3>${documentLink(t.doc)}${t.id==='insurance'?documentLink('will'):t.id==='medical'?documentLink('receipt'):''}</div>${['insurance','medical'].includes(id)?`<button class="text-link" data-action="task-evidence">Compare the evidence ${icon('arrow')}</button>`:''}<div class="subtle-box">${t.id==='insurance'?'Ask the insurer to confirm current policy status and its recorded beneficiary. This archive cannot establish entitlement.':t.id==='medical'?'Ask for an updated itemized balance and confirm where the $400 payment was applied.':t.id==='storage'?'First ask how a family member can arrange access. Do not assume belongings can be discarded.':'Use this as an organizing step. Taking an action here does not contact or update any provider.'}</div>`,`${button(status(t)==='waiting'?'Resume action':'Waiting for a reply','task-wait')}${button(status(t)==='done'?'Reopen action':'Mark as completed','task-complete',true,'check')}`)}
window.openTask=openTask;

function documentsPage(){return heading('YOUR FAMILY’S PAPER TRAIL','Everything, brought together.','A place for the records you have, and the details you’re still piecing together.',button('Add documents','import',true,'plus'))+`<div class="library-summary"><div>${icon('files')}<strong>${allRecords().length}</strong><span>sample records</span></div><div>${icon('eye')}<strong>3</strong><span>review topics</span></div><div>${icon('lock')}<span>Fictional records only<br><small>No external accounts connected</small></span></div></div><div class="library-tools"><label class="search-field">${icon('search')}<input id="document-search" aria-label="Search documents" placeholder="Search names, documents or details…" value="${escapeHTML(state.query)}"></label><label class="type-filter"><span>Type</span><select id="document-type" aria-label="Document type"><option value="all">All types</option>${['PDF','Email','CSV','Transcript'].map(v=>`<option ${state.docFilter===v?'selected':''}>${v}</option>`).join('')}</select></label></div><section class="library"><div class="library-head"><span>DOCUMENT</span><span>CATEGORY</span><span>RECORD DATE</span><span>REVIEW STATUS</span><span></span></div><div id="document-results" aria-live="polite">${documentRows()}</div></section><p class="fine below-note">The preview includes readable excerpts, not original legal documents. Search covers all text in these sample records.</p><div class="library-bottom"><div>${icon('link')}<div><h3>The details don’t have to stay disconnected.</h3><p>See how a policy letter, a will and a payment receipt connect to the steps in your plan.</p></div></div><a class="text-link" href="#evidence">Open evidence review ${icon('arrow')}</a></div>`}
function documentRows(){const list=allRecords().filter(d=>(state.docFilter==='all'||d.type===state.docFilter)&&Object.values(d).join(' ').toLowerCase().includes(state.query.toLowerCase()));return list.length?list.map(d=>`<button class="document-row" data-action="document" data-id="${d.id}"><span class="doc-title"><span class="file-badge ${d.type.toLowerCase()}">${d.type==='Email'?icon('mail'):d.type==='Transcript'?icon('mic'):icon('files')}</span><span><strong>${d.title}</strong><small>${d.file}</small></span></span><span>${d.category}</span><span>${d.date}</span><span class="pill ${d.flag==='Review suggested'?'amber':'neutral'}">${d.flag}</span>${icon('chevron')}</button>`).join(''):`<div class="empty-state">${icon('search')}<h2>No matching records.</h2><p>Try “policy”, “payment”, or a different document type.</p></div>`}
function recordPaper(d){return `<article class="record-paper"><div class="paper-label">FICTIONAL SOURCE EXCERPT <span>${d.type}</span></div><h2>${d.intro}</h2><div class="paper-meta">${d.issuer}<br>${d.date}</div><p>${escapeHTML(d.text).replace(/\n/g,'<br>')}</p><blockquote>${escapeHTML(d.highlight).replace(/\n/g,'<br>')}</blockquote><p>${escapeHTML(d.end).replace(/\n/g,'<br>')}</p><div class="paper-bottom">Afterword sample archive <span>1 / 1</span></div></article>`}
function openDocument(id){const d=allRecords().find(d=>d.id===id);if(!d)return;modal(d.title,recordPaper(d),button('Back to workspace','close-modal'));}
function openImport(){modal('Bring a little more together',`<div class="import-illustration">${icon('files')}${icon('mail')}${icon('mic')}</div><h3 class="center-title">Every record has a place here.</h3><p class="center-copy">Explore the import experience with one extra fictional family letter.</p><div class="import-zone">${icon('upload')}<strong>A letter for a rainy day</strong><span>Text transcript · original fictional passage</span></div><div class="subtle-box">This is a design preview. Real file uploads, email connections and document analysis are not connected. Please keep personal records out of this demo.</div>`,button(state.imported?'Sample already added':'Add sample letter','sample-import',!state.imported,'plus'));}
window.openImport=openImport;

const findings={insurance:{label:'Life insurance',hint:'Different recipients named',icon:'shield',sources:['policy','will'],title:'Two records. An important distinction.',lead:'A 2019 policy letter names Maya. A 2024 family copy of a will names Priya for the estate. Those statements may refer to different assets.',known:'The historical policy letter mentions $250,000 and names Maya Rao as its primary beneficiary at that time.',unknown:'Current coverage, later beneficiary changes, and who is entitled to a benefit have not been confirmed.',next:'Ask the insurer for its current policy and beneficiary information, and what authority is required to request it.',task:'insurance'},medical:{label:'Medical balance',hint:'A later payment needs checking',icon:'files',sources:['medical','receipt'],title:'Before paying, connect the two records.',lead:'The invoice shows $1,240. A later receipt records a $400 payment, but does not explicitly connect it to that invoice.',known:'The invoice is dated September 10. The receipt records a $400 payment on September 14.',unknown:'Whether this payment was applied to this invoice, and the current amount due.',next:'Request an updated itemized balance and ask where the payment was applied.',task:'medical'},storage:{label:'Storage space',hint:'Belongings may still be inside',icon:'book',sources:['storage'],title:'There may be more than a bill here.',lead:'A recurring storage charge is also a reminder that personal belongings may need to be collected.',known:'A September renewal email records a monthly charge of $129 and asks for collection before closing.',unknown:'What is inside, who is authorized to enter, and the terms for ending the rental.',next:'Arrange a visit and confirm access requirements before deciding whether to cancel.',task:'storage'}};
function evidencePage(){const f=findings[state.selectedFinding];const active=state.evidenceSource&&f.sources.includes(state.evidenceSource)?state.evidenceSource:f.sources[0];return heading('FOLLOW THE EVIDENCE','Clarity starts with the source.','See what the records say, what they leave open, and a sensible next step.')+`<div class="evidence-tabs" role="group" aria-label="Choose evidence topic">${Object.entries(findings).map(([id,v])=>`<button class="evidence-tab ${id===state.selectedFinding?'active':''}" data-action="finding" data-id="${id}" aria-pressed="${id===state.selectedFinding}">${icon(v.icon)}<span><strong>${v.label}</strong><small>${v.hint}</small></span>${state.reviewed.includes(id)?icon('check'):''}</button>`).join('')}</div><div class="evidence-workspace"><section class="finding-panel"><div class="finding-status"><span class="pill amber">${icon('review')}Confirmation needed</span><span>${f.sources.length} source${f.sources.length>1?'s':''}</span></div><h2>${f.title}</h2><p class="finding-lead">${f.lead}</p><div class="evidence-fact"><div>${icon('check')} IN THE RECORD</div><p>${f.known}</p></div><div class="evidence-fact unresolved"><div>${icon('search')} STILL UNKNOWN</div><p>${f.unknown}</p></div><div class="evidence-fact next-step"><div>${icon('arrow')} A HELPFUL NEXT STEP</div><p>${f.next}</p></div><div class="evidence-actions"><button class="button primary" data-action="finding-letter">Prepare a question ${icon('arrow')}</button><button class="button" data-action="review-finding">${icon('check')}${state.reviewed.includes(state.selectedFinding)?'Read · Undo':'Mark as read'}</button></div><p class="fine">“Read” means you have read this finding. It does not resolve the unknowns or confirm a legal conclusion.</p></section><section class="source-panel"><div class="source-toolbar"><h3>${icon('files')} Source records</h3><span>Read them side by side</span></div><div class="source-tabs" role="group" aria-label="Choose source record">${f.sources.map((id,i)=>`<button data-action="evidence-source" data-id="${id}" class="${active===id?'selected':''}" aria-pressed="${active===id}">${i+1}. ${records.find(r=>r.id===id).title}</button>`).join('')}</div>${recordPaper(records.find(d=>d.id===active))}<div class="source-caption">${icon('eye')}Highlight marks the relevant excerpt, not a verified conclusion.</div></section></div>`}

const letterTemplates={insurance:{title:'Ask about a policy',recipient:'Cedar Life — policy services',subject:'Request for information about an existing policy',body:'I am helping organize the affairs of Arun Rao and found a policy letter dated June 12, 2019.\n\nPlease let me know how to confirm whether the policy remains active and what information or authorization you require before discussing its current beneficiary designation.\n\nI understand that the historical letter may not reflect current records. Please tell me the appropriate next steps and secure method for providing any required documents.'},medical:{title:'Clarify a medical balance',recipient:'Cedar Clinic — billing team',subject:'Request for an updated itemized balance',body:'I am helping organize the affairs of Arun Rao. I found an invoice dated September 10, 2026 showing $1,240 and a receipt dated September 14, 2026 for $400.\n\nPlease explain what authorization is required to discuss the account. Once that is established, could you confirm whether this payment was applied to the invoice and provide an updated itemized balance?\n\nPlease let me know the secure way to provide any documents you require.'},storage:{title:'Arrange access to belongings',recipient:'Valley Storage — customer team',subject:'Request for information about arranging a storage visit',body:'I am helping organize the affairs of Arun Rao and found a storage renewal email dated September 2, 2026.\n\nBefore making any changes, I would like to understand how an authorized family member can arrange a visit and collect personal belongings. Please explain the access requirements, documents needed, and any relevant notice terms.\n\nThis message is an information request and is not a request to cancel the rental.'}};
let letterType='insurance';let letterDraft=state.drafts.insurance?{...state.drafts.insurance}:null;let letterPreview=false;const sessionDrafts={};
const draftSaved=d=>state.storageAvailable!==false&&!!state.drafts[letterType]&&['name','recipient','subject','body'].every(k=>state.drafts[letterType][k]===d[k]);
function lettersPage(){const t=letterTemplates[letterType];const d=letterDraft||{name:'Priya Rao',recipient:t.recipient,subject:t.subject,body:t.body};return heading('FINDING THE WORDS','A thoughtful start to a difficult letter.','Prepare a clear question, make it your own, and decide when you’re ready to use it.')+`<div class="letter-layout"><aside class="letter-options"><div class="eyebrow">START WITH A TEMPLATE</div>${Object.entries(letterTemplates).map(([id,l])=>`<button class="letter-template ${id===letterType?'active':''}" data-action="letter-template" data-id="${id}">${icon(id==='insurance'?'shield':id==='medical'?'files':'book')}<span>${l.title}</span>${icon('chevron')}</button>`).join('')}<div class="letter-guidance"><h3>Still your words.</h3><p>These drafts ask for information without claiming authority or entitlement. Check every detail before using them.</p><div>${icon('check')} Editable by you</div><div>${icon('check')} Nothing sent automatically</div><div>${icon('check')} Download when you’re ready</div></div></aside><section class="letter-editor"><div class="editor-toolbar"><span>${icon('mail')} ${letterPreview?'Your letter preview':'Untitled draft'} <span class="pill neutral" id="draft-state">${draftSaved(d)?'Saved in this browser':'Draft'}</span></span><div><button class="text-link" data-action="letter-preview">${icon(letterPreview?'edit':'eye')}${letterPreview?'Edit letter':'Preview'}</button></div></div><form id="letter-form"><div class="letter-paper"><div class="letter-monogram">a.</div><div class="letter-date">September 21, 2026 · sample draft</div>${letterPreview?`<div class="letter-read"><p>To ${escapeHTML(d.recipient)}</p><h2>${escapeHTML(d.subject)}</h2><p>Dear team,</p><p>${escapeHTML(d.body).replace(/\n/g,'<br>')}</p><p>Thank you,<br>${escapeHTML(d.name)}</p></div>`:`<div class="fields-two"><label class="field"><span>Your name</span><input name="name" value="${escapeHTML(d.name)}" required maxlength="120"></label><label class="field"><span>Recipient / team</span><input name="recipient" value="${escapeHTML(d.recipient)}" required maxlength="200"></label></div><label class="field"><span>Subject</span><input name="subject" value="${escapeHTML(d.subject)}" required maxlength="240"></label><div class="letter-salutation">Dear team,</div><label class="field"><span class="sr-only">Letter body</span><textarea name="body" rows="10" required maxlength="12000">${escapeHTML(d.body)}</textarea></label><div class="letter-salutation">Thank you,<br><span id="letter-signature">${escapeHTML(d.name)}</span></div>`}</div><div class="editor-footer"><span class="fine">${icon('lock')}Sample drafts stay in this browser. Use fictional details.</span><div class="button-row"><button type="button" class="button" data-action="save-letter">Save draft</button><button type="button" class="button primary" data-action="download-letter">${icon('download')}Download letter</button></div></div></form></section></div>`}
function captureLetter(){const f=$('#letter-form');if(!letterPreview&&f){letterDraft=Object.fromEntries(new FormData(f));}return letterDraft||{name:'Priya Rao',...letterTemplates[letterType]};}
function validLetter(){return letterPreview||$('#letter-form').reportValidity();}

const memories=[{id:'tea',type:'LETTER',title:'For a rainy day',date:'November 17, 2023',quote:'“Make the tea first. The rest can wait a few minutes.”',text:'For a day when things feel a little too much,\n\nMake the tea first. The rest can wait a few minutes. You always did try to carry everything at once.\n\nI hope you remember that a good day does not have to be a remarkable day. Sometimes it is just a hot cup, an open window, and someone you love on the phone.\n\nWith love, Dad.'},{id:'sunday',type:'RECIPE',title:'The Sunday breakfast ritual',date:'Family notebook',quote:'A little more ginger. Always.',text:'Put the kettle on before anything else. Grate a little more ginger than you think you need.\n\nTwo cups of water, one cup of milk, tea, ginger and cardamom. Simmer slowly. There was never an exact measurement for the conversation.\n\nAn original fictional recipe note for the design preview.'},{id:'walk',type:'VOICE TRANSCRIPT',title:'The long way home',date:'April 6, 2024',quote:'“Let’s take the road by the water. We have time.”',text:'I know there is a quicker road, but let’s take the one by the water. We have time.\n\nIt’s funny how the longer way home is sometimes the part you remember.\n\nFictional transcript. There is no original audio attached.'}];
function memoriesPage(){const list=state.memoryFilter==='saved'?memories.filter(m=>state.favorite.includes(m.id)):memories;return `<div class="memory-top"><div><div class="eyebrow">THE PERSONAL THINGS</div><h1>More than what’s left to do.</h1><p>A few words. A familiar recipe. The things that feel like them.</p></div>${icon('heart')}</div><section class="quiet-archive-intro"><blockquote>“Make the tea first.<br>The rest can wait a few minutes.”</blockquote><div><div class="eyebrow">FROM THE FAMILY ARCHIVE</div><p>An excerpt from “For a rainy day.”<br>November 17, 2023 · fictional family letter</p><button class="text-link" data-action="read-memory" data-id="tea">Read the letter ${icon('arrow')}</button></div></section><div class="memory-nav"><div class="filter-bar" role="group" aria-label="Filter memories"><button class="filter ${state.memoryFilter!=='saved'?'selected':''}" data-action="memory-filter" data-filter="all" aria-pressed="${state.memoryFilter!=='saved'}">All memories <span>3</span></button><button class="filter ${state.memoryFilter==='saved'?'selected':''}" data-action="memory-filter" data-filter="saved" aria-pressed="${state.memoryFilter==='saved'}">Saved for later <span>${state.favorite.length}</span></button></div><span>Fictional passages, written for this preview</span></div><div class="memory-grid">${list.map((m,i)=>`<article class="memory-card memory-${m.id}"><div class="memory-card-head"><span>${icon(m.type==='LETTER'?'mail':m.type==='RECIPE'?'book':'mic')}${m.type}</span><button class="icon-button favorite ${state.favorite.includes(m.id)?'saved':''}" data-action="favorite" data-id="${m.id}" aria-label="${state.favorite.includes(m.id)?'Unsave':'Save'} ${m.title}" aria-pressed="${state.favorite.includes(m.id)}">${icon('heart')}</button></div><div class="memory-quote">${m.quote}</div><h3>${m.title}</h3><small>${m.date}</small><button class="text-link" data-action="read-memory" data-id="${m.id}">${m.type==='RECIPE'?'Open the recipe':m.type==='LETTER'?'Read the letter':'Read the transcript'} ${icon('arrow')}</button></article>`).join('')||`<div class="empty-state">${icon('heart')}<h2>A place to return to.</h2><p>Save a memory using its heart button and it will be here.</p></div>`}</div><p class="memory-bottom-note">There is no right order, and no right time.</p>`}

const questions=['What should I look at first?','What do we know about the insurance?','Which subscriptions appear in the records?','Has the medical bill been paid?'];
const answers=[{title:'Start with one detail that needs confirming.',body:'The life insurance records are worth reviewing before assuming a benefit is available. One names a policy beneficiary in 2019; another names an estate recipient in 2024. You can compare both, then prepare a question for the insurer.',uncertain:'Neither record confirms who would receive a payment today.',sources:['policy','will'],route:'evidence',cta:'Compare the two records'}, {title:'There is a historical policy letter, not confirmation of a current benefit.',body:'The June 2019 letter mentions $250,000 of coverage and names Maya Rao as primary beneficiary at that time. The 2024 family copy of a will names Priya for the estate. Those designations may apply to different assets.',uncertain:'Current coverage and any later beneficiary changes are unknown.',sources:['policy','will'],route:'evidence',cta:'Review the insurance evidence'}, {title:'Two recurring subscriptions appear in the statement.',body:'Harbor Gym is listed at $39.99 and Streamly at $15.49, totaling $55.48. There is also a separate $129 storage charge, but personal belongings may need to be collected before making changes to that rental.',uncertain:'A transaction does not prove account ownership or cancellation terms.',sources:['statement','storage'],route:'plan',cta:'Open your action plan'}, {title:'A payment is recorded, but the current balance is still unclear.',body:'The September 10 invoice shows $1,240. A September 14 receipt records a $400 payment. If applied to that invoice, $840 would remain, but the sample receipt does not establish that link.',uncertain:'Ask the provider to confirm the allocation and issue an updated balance.',sources:['medical','receipt'],route:'evidence',cta:'Compare the invoice and receipt'}];
let conversation=[];
function askPage(){return `<div class="ask-layout"><section class="ask-main"><div class="ask-intro"><span class="ask-orb">${icon('spark')}</span><div class="eyebrow">A LITTLE HELP UNTANGLING THINGS</div><h1>Let’s make sense of it, together.</h1><p>Ask about the sample records. Every answer shows what it comes from.</p></div><div class="question-grid">${questions.map((q,i)=>`<button data-action="sample-question" data-index="${i}">${icon(['plan','shield','refresh','files'][i])}<span>${q}</span>${icon('arrow')}</button>`).join('')}</div><div id="conversation" aria-live="polite">${conversation.map(chatMarkup).join('')}</div><form id="ask-form" class="ask-composer"><label class="sr-only" for="ask-input">Your question about the sample records</label><textarea id="ask-input" rows="2" maxlength="1000" placeholder="What would help you feel a little clearer?" required></textarea><div><span>${icon('files')} ${allRecords().length} sample records · scripted demo</span><button class="button primary" type="submit" aria-label="Ask your question">${icon('arrow')}</button></div></form><p class="ask-disclaimer">Sample answers demonstrate the experience. Open-ended AI, legal guidance and live account information are not connected.</p></section><aside class="ask-aside"><div class="eyebrow">ALWAYS GROUNDED</div><h2>You can see<br>where it comes from.</h2><p>Afterword’s planned answers start with your records and leave room for what isn’t known.</p><div class="ask-principle">${icon('files')}<div><h3>The source stays close</h3><p>Open the exact excerpt behind an answer.</p></div></div><div class="ask-principle">${icon('search')}<div><h3>Unknown is an answer</h3><p>A missing record stays a missing record.</p></div></div><div class="ask-principle">${icon('heart')}<div><h3>You choose the next step</h3><p>No messages sent or accounts changed for you.</p></div></div><a class="text-link" href="#privacy">How processing is designed ${icon('arrow')}</a></aside></div>`}
function chatMarkup(c){return `<div class="chat-turn"><div class="user-question"><span class="avatar">PR</span><p>${escapeHTML(c.question)}</p></div><article class="answer"><div class="answer-brand">${icon('spark')}AFTERWORD <span>Sample response</span></div><h2>${c.answer.title}</h2><p>${c.answer.body}</p>${c.answer.uncertain?`<div class="answer-uncertainty">${icon('info')}<span>${c.answer.uncertain}</span></div>`:''}<div class="answer-sources">${(c.answer.sources||[]).map(documentLink).join('')}</div>${c.answer.route?`<button class="text-link" data-action="answer-next" data-route="${c.answer.route}" data-topic="${c.topic||'insurance'}">${c.answer.cta} ${icon('arrow')}</button>`:''}</article></div>`}
function askQuestion(q,index){if(index===undefined){const text=q.toLowerCase();index=/insurance|policy|beneficiary/.test(text)?1:/subscription|recurring|gym|stream/.test(text)?2:/medical|bill|receipt|paid/.test(text)?3:/first|start|next step/.test(text)?0:-1;}conversation.push({question:q,topic:index===3?'medical':'insurance',answer:index>=0?answers[index]:{title:'That isn’t covered by this sample.',body:'This design preview can demonstrate questions about the insurance records, subscriptions, medical balance or where to begin. It does not analyze new questions with a live model. Choose one of the prompts above to explore a grounded answer.',sources:[]}});render();$('#conversation')?.lastElementChild?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}

function privacyPage(){return heading('PRIVATE BY DESIGN. CLEAR ABOUT THE DETAILS.','Your family’s story deserves care.','Explore how Afterword is intended to process an archive on an HP ZGX Nano.')+`<section class="device-banner"><div><span class="dark-tag">PROPOSED ARCHITECTURE · NOT CONNECTED</span><h2>A powerful little home<br>for deeply personal things.</h2><p>The intended product keeps document analysis close to the family. This preview shows the design, not a running device or a privacy guarantee.</p><div class="device-caption">${icon('server')} HP ZGX Nano G1n <span>Target platform</span></div></div><div class="nano-illustration" role="img" aria-label="Concept illustration of an edge AI computer"><div class="nano-box"><span class="nano-top">afterword</span><div class="nano-front"><i></i><i></i><i></i><i></i><b>LOCAL AI</b></div></div><div class="nano-ground"></div></div></section><div class="privacy-columns"><section class="processing-card"><div class="section-title"><h2>Where the work is intended to happen</h2><span class="pill neutral">Design map</span></div><div class="processing-flow">${[{n:'00',title:'Read the file',text:'Extract text from native PDFs, emails, CSVs and transcripts.',tag:'Local parser',icon:'files'},{n:'01',title:'Organize the details',text:'A smaller local model identifies entities and links them to source spans.',tag:'Proposed 8B model',icon:'grid'},{n:'02',title:'Compare the evidence',text:'A larger local model reviews difficult relationships and flags open questions.',tag:'Proposed 70B model',icon:'eye'},{n:'03',title:'Prepare a next step',text:'Show the finding with its sources. The family reviews and decides.',tag:'Human approval',icon:'heart'}].map(v=>`<div class="processing-stage"><span class="stage-number">${v.n}</span><div><h3>${v.title}</h3><p>${v.text}</p><span>${v.tag}</span></div>${icon(v.icon)}</div>`).join('')}</div><p class="fine">Model sizes are planning targets. Memory use, speed and accuracy require benchmarking on the actual hardware.</p></section><aside><section class="privacy-panel"><div class="section-title"><h2>What is connected right now</h2>${icon('lock')}</div>${[['HP workstation','Not connected'],['AI inference','Not running'],['Email & bank accounts','Not connected'],['Cloud AI calls','Not implemented']].map(([k,v])=>`<div class="connection-row"><span>${k}</span><strong>${v}</strong></div>`).join('')}<p class="fine">Only fictional records and browser-side interactions power this prototype.</p></section><section class="privacy-panel exposure-panel"><div class="eyebrow">BEFORE ANY OPTIONAL CLOUD STEP</div><h2>See the boundary.</h2><p>The intended product should show exactly what would leave the device, with explicit permission. That boundary is not implemented here.</p><button class="text-link" data-action="exposure">Explore a sample exposure review ${icon('arrow')}</button></section></aside></div><section class="browser-storage"><div>${icon('settings')}<div><h3>Your preview preferences</h3><p>Completed steps, reviewed findings, saved memories, a sample letter draft and reading size stay in this browser. No real archive is stored.</p></div></div><button class="button" data-action="preferences">Reading preferences</button></section>`}

const research=[{year:'2025',kind:'RESEARCH PAPER',title:'Generative Interfaces for Language Models',url:'https://arxiv.org/html/2508.19227v1',detail:'Task-specific interfaces for information-heavy work.',applied:'Separate evidence, planning, document and memory layouts instead of forcing every task into a chat.',limit:'100 generated prompts and pairwise preferences; does not establish estate-task accuracy or benefits for bereaved users.'},{year:'2026',kind:'IUI PAPER',title:'In-Situ Adaptive Interfaces for Online Browsing',url:'https://gracekim.me/docs/AdaptiveInterfaces.pdf',detail:'User control in adaptive interfaces.',applied:'Stable navigation, reversible filters, explicit review controls and persistent reading preferences.',limit:'Qualitative study of 10 frequent shoppers; no controlled baseline or causal efficiency claim.'},{year:'2025',kind:'RESEARCH PAPER',title:'Improving Human Verification of LLM Reasoning through Interactive Explanation Interfaces',url:'https://arxiv.org/html/2510.22922v1',detail:'Inspecting information through interactive representations.',applied:'Source excerpts next to findings, relevant text highlighted, and uncertainty kept visible.',limit:'125 undergraduates working with math explanations and injected errors; not an estate or grief study.'},{year:'CURRENT GUIDANCE',kind:'GOOGLE DESIGN',title:'Material 3 Expressive research',url:'https://design.google/library/expressive-material-design-google-research',detail:'Purposeful hierarchy and visual emphasis.',applied:'One prominent next action, a restrained expressive hero, and distinct surfaces for distinct jobs.',limit:'Afterword borrows hierarchy principles, not Google’s branding or claims of product validation.'},{year:'CURRENT GUIDANCE',kind:'MICROSOFT FLUENT 2',title:'Color and motion with a purpose',url:'https://fluent2.microsoft.design/color',detail:'Neutral surfaces, consistent semantic colors and readable contrast.',applied:'Graphite actions, silver and white surfaces, labeled amber review states, brief transitions and reduced-motion support.',limit:'Colors are an editorial brand decision, not a universal claim about emotional effects.'},{year:'WCAG 2.2',kind:'ACCESSIBILITY',title:'Reflow, readable contrast and usable targets',url:'https://www.w3.org/WAI/WCAG22/Understanding/reflow.html',detail:'Design for different screens and ways of interacting.',applied:'Responsive layouts, semantic controls, keyboard focus, accessible dialogs and adjustable reading size.',limit:'Implemented safeguards are not equivalent to a completed independent accessibility audit.'}];
function designPage(){return heading('THE THINKING BEHIND THE EXPERIENCE','Built with care, informed by research.','A design system for practical clarity and personal space. Research checked September 2026.')+`<section class="design-manifesto"><div class="eyebrow">ONE IDENTITY. DIFFERENT KINDS OF SPACE.</div><h2>Calm doesn’t have to mean empty.<br>Detailed doesn’t have to mean overwhelming.</h2><p>Afterword gives each task the layout it needs: a plan to move through, evidence to compare, a letter to edit, and a quieter place to remember.</p><div class="swatches"><div style="--swatch:#15191f"><i></i><strong>Graphite</strong><span>Primary actions</span></div><div style="--swatch:#f0f2f6"><i></i><strong>Silver</strong><span>Reading space</span></div><div style="--swatch:#175cff"><i></i><strong>Cobalt</strong><span>Focused emphasis</span></div><div style="--swatch:#fbf1dc"><i></i><strong>Soft amber</strong><span>Labeled uncertainty</span></div></div></section><div class="section-title research-title"><h2>Articles and papers → design decisions</h2><span>Primary sources</span></div><div class="research-grid">${research.map(r=>`<article class="research-card"><div class="eyebrow">${r.kind} · ${r.year}</div><h2><a href="${r.url}" target="_blank" rel="noopener noreferrer">${r.title} ${icon('external')}</a></h2><p>${r.detail}</p><h3>In this prototype</h3><p>${r.applied}</p><details><summary>What the source does not prove</summary><p>${r.limit}</p></details></article>`).join('')}</div><section class="prototype-scope"><div><h2>What you can try today</h2><p>Navigate twelve distinct views, filter and search records, compare source excerpts, complete and reopen actions, edit and download a letter, save memories and explore scripted questions.</p></div><div><h2>What remains to be engineered</h2><p>Authentication, consent and roles; encrypted archive ingestion; parsers and local model inference; retrieval and evidence validation; calibrated uncertainty; jurisdiction-aware rules; device security; real accessibility and family usability studies.</p></div></section><p class="fine">Service references reviewed for language and workflow: <a href="https://www.empathy.com/solutions/loss-support" target="_blank" rel="noopener noreferrer">Empathy</a>, <a href="https://www.hellosunset.com/" target="_blank" rel="noopener noreferrer">Sunset</a>, and <a href="https://www.settld.care/" target="_blank" rel="noopener noreferrer">Settld</a>. No affiliation or originality claim. HP product imagery identifies the target hardware; Afterword is an independent concept. All personal passages and records are fictional.</p>`}

Object.assign(window.views,{plan:planPage,documents:documentsPage,evidence:evidencePage,letters:lettersPage,memories:memoriesPage,ask:askPage,privacy:privacyPage,design:designPage});
Object.assign(window.actions,{
 'filter-plan':a=>{state.filter=a.dataset.filter;render()},
 'task-complete':()=>{const id=state.activeTask;state.completed=state.completed.includes(id)?state.completed.filter(v=>v!==id):[...state.completed,id];state.waiting=state.waiting.filter(v=>v!==id);persist();$('#detail-dialog').close();render();toast(state.completed.includes(id)?'Action marked completed. You can reopen it anytime.':'Action reopened.')},
 'task-wait':()=>{const id=state.activeTask;state.waiting=state.waiting.includes(id)?state.waiting.filter(v=>v!==id):[...state.waiting,id];state.completed=state.completed.filter(v=>v!==id);persist();$('#detail-dialog').close();render();toast('Action status updated.')},
 'task-evidence':()=>{state.selectedFinding=state.activeTask;$('#detail-dialog').close();go('evidence')},
 document:a=>openDocument(a.dataset.id),
 'sample-import':()=>{if(state.imported){toast('This sample letter is already in your library.');return}state.imported=true;state.query='';state.docFilter='all';$('#detail-dialog').close();go('documents');toast('One fictional letter added to the sample library.')},
 finding:a=>{state.selectedFinding=a.dataset.id;state.evidenceSource=null;render()},
 'evidence-source':a=>{state.evidenceSource=a.dataset.id;render()},
 'review-finding':()=>{const id=state.selectedFinding;state.reviewed=state.reviewed.includes(id)?state.reviewed.filter(v=>v!==id):[...state.reviewed,id];persist();render();toast(state.reviewed.includes(id)?'Marked as read. Unknowns still need confirmation.':'Review mark removed.')},
 'finding-letter':()=>{letterType=state.selectedFinding;letterDraft=sessionDrafts[letterType]||null;letterPreview=false;go('letters')},
 'letter-template':a=>{sessionDrafts[letterType]=captureLetter();letterType=a.dataset.id;letterDraft=sessionDrafts[letterType]||null;letterPreview=false;render()},
 'letter-preview':()=>{if(!validLetter())return;captureLetter();letterPreview=!letterPreview;render()},
 'save-letter':()=>{if(!validLetter())return;state.savedDraft={...captureLetter(),template:letterType};persist();render();toast('Sample draft saved in this browser. Nothing has been sent.')},
 'download-letter':()=>{if(!validLetter())return;const d=captureLetter();const text=`AFTERWORD — SAMPLE DRAFT\nFictional details. Review before use.\n\nTo: ${d.recipient}\nSubject: ${d.subject}\n\nDear team,\n\n${d.body}\n\nThank you,\n${d.name}\n`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='afterword-letter-draft.txt';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);modal('Your letter is ready',`<p>A text-file download has been requested. If your browser does not offer it, you can select and copy the letter below. Nothing has been sent.</p><label class="field"><span>Exported draft</span><textarea rows="12" readonly>${escapeHTML(text)}</textarea></label>`,button('Back to letter','close-modal'))},
 'memory-filter':a=>{state.memoryFilter=a.dataset.filter;render()},
 favorite:a=>{const id=a.dataset.id;state.favorite=state.favorite.includes(id)?state.favorite.filter(v=>v!==id):[...state.favorite,id];persist();render();toast(state.favorite.includes(id)?'Saved for a quiet moment later.':'Memory removed from your saved view.')},
 'read-memory':a=>{const m=memories.find(m=>m.id===a.dataset.id);modal(m.title,`<div class="memory-reading"><div class="eyebrow">${m.type} · ${m.date}</div><p>${escapeHTML(m.text).replace(/\n/g,'<br>')}</p><small>Original fictional writing for this preview.</small></div>`,button('Back to memories','close-modal'))},
 'sample-question':a=>askQuestion(questions[Number(a.dataset.index)],Number(a.dataset.index)),
 'answer-next':a=>{state.selectedFinding=a.dataset.topic;go(a.dataset.route)},
 exposure:()=>modal('A sample boundary review',`<p>The proposed cloud fallback would receive a general question only after you review the proposed payload. This preview makes no AI request.</p><div class="exposure-comparison"><div><span class="eyebrow">KEEP ON THE DEVICE</span><p>Names, policy references, amounts, family documents and source excerpts.</p></div><div><span class="eyebrow">ILLUSTRATIVE GENERAL QUESTION</span><p>“What information might an insurer request before discussing a deceased policyholder’s account?”</p></div></div><div class="subtle-box">Removing names does not by itself guarantee privacy. The real product needs policy enforcement, leakage testing and explicit consent before any external processing.</div>`,button('Close review','close-modal'))
});
document.addEventListener('input',e=>{if(e.target.id==='document-search'){state.query=e.target.value;$('#document-results').innerHTML=documentRows()}if(e.target.closest('#letter-form')){captureLetter();const sig=$('#letter-signature');if(sig)sig.textContent=letterDraft.name;const badge=$('#draft-state');if(badge)badge.textContent=draftSaved(letterDraft)?'Saved in this browser':'Unsaved changes'}});
document.addEventListener('change',e=>{if(e.target.id==='document-type'){state.docFilter=e.target.value;$('#document-results').innerHTML=documentRows()}});
document.addEventListener('submit',e=>{if(e.target.id==='ask-form'){e.preventDefault();const q=$('#ask-input').value.trim();if(q)askQuestion(q)}if(e.target.id==='letter-form')e.preventDefault()});
// Browser-native, read-only tool. The visible UI remains the source of state.
if(navigator.modelContext?.registerTool){try{navigator.modelContext.registerTool({name:'read_afterword_sample_plan',description:'Read the fictional action plan currently displayed by the Afterword design preview. No live estate or account information.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>({content:[{type:'text',text:JSON.stringify(tasks.map(t=>({title:t.title,status:status(t),source:t.source})))}]})})}catch{}}
// Keep mobile navigation outside the focus order until explicitly opened.
const mobileViewport=matchMedia('(max-width:740px)');
const syncNavigation=()=>{const side=$('.sidebar');const isOpen=mobileViewport.matches&&side?.classList.contains('open');if(side)side.inert=mobileViewport.matches&&!isOpen;const work=$('.work-area');if(work)work.inert=!!isOpen};
afterRender=()=>{const main=$('#main');if(main)main.tabIndex=-1;syncNavigation();if(state.route==='overview'){const n=state.imported?9:8;const summary=$('.summary-bottom');if(summary)summary.lastElementChild.innerHTML='<b>'+n+'</b> records gathered'}};
mobileViewport.addEventListener('change',syncNavigation);
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();$('#main').scrollIntoView({block:'start'});}if(e.target.closest('[data-action="menu"]')){syncNavigation();if($('.sidebar').classList.contains('open'))$('.sidebar .brand').focus();else $('.menu-button').focus()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('.sidebar')?.classList.contains('open')){$('.sidebar').classList.remove('open');$('.menu-button').setAttribute('aria-expanded','false');syncNavigation();$('.menu-button').focus()}});
window.addEventListener('hashchange',()=>$('#main')?.focus({preventScroll:true}));
render();
